package com.sledge.browser.android.gate

import android.content.Context
import android.content.pm.PackageManager
import androidx.core.content.ContextCompat
import com.sledge.browser.gate.PermissionGate
import com.sledge.browser.gate.PlatformPermission

// Generated by the desktop mirror. The build hook refreshes this file.

/**
 * Reports permissions Android has already granted. The app's own request
 * flow stays where it was written. Desktop uses a different prompt.
 */
class AndroidPermissionGate(private val context: Context) : PermissionGate {
    override fun ask(permission: PlatformPermission, onResult: (Boolean) -> Unit) {
        val granted = ContextCompat.checkSelfPermission(context, permission.androidName) ==
            PackageManager.PERMISSION_GRANTED
        onResult(granted)
    }
}
